import{_ as a,c as t,o as r,a3 as i}from"./chunks/framework.Dk6sf0Ip.js";const m=JSON.parse('{"title":"Reporte de Trazabilidad de Cubiertas","description":"","frontmatter":{},"headers":[],"relativePath":"reportes/trazabilidadCubiertas/index.md","filePath":"reportes/trazabilidadCubiertas/index.md","lastUpdated":1759946186000}'),o={name:"reportes/trazabilidadCubiertas/index.md"};function l(s,e,d,n,c,u){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="reporte-de-trazabilidad-de-cubiertas" tabindex="-1">Reporte de Trazabilidad de Cubiertas <a class="header-anchor" href="#reporte-de-trazabilidad-de-cubiertas" aria-label="Permalink to &quot;Reporte de Trazabilidad de Cubiertas&quot;">​</a></h1><h2 id="objetivo-del-reporte" tabindex="-1">Objetivo del reporte <a class="header-anchor" href="#objetivo-del-reporte" aria-label="Permalink to &quot;Objetivo del reporte&quot;">​</a></h2><p>El reporte permite visualizar el <strong>historial completo de cada cubierta</strong>, desde que ingresa al sistema hasta cada movimiento posterior (recapado, rotación, baja, etc.). De esta manera se logra un control sobre su uso, ubicación, estado y proveedor.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>💡 <a href="./../../CasosParticulares/cubiertas/Cubiertas.html">Ver Cubiertas</a></p></div><h2 id="_1-panel-lateral-izquierdo-–-lista-de-cubiertas" tabindex="-1">1. Panel lateral izquierdo – Lista de cubiertas <a class="header-anchor" href="#_1-panel-lateral-izquierdo-–-lista-de-cubiertas" aria-label="Permalink to &quot;1. Panel lateral izquierdo – Lista de cubiertas&quot;">​</a></h2><p>En la columna izquierda aparece un listado con todas las cubiertas registradas.</p><ul><li>Cada cubierta está identificada por un <strong>código único</strong> (ejemplo: <em>FATE 987693</em>).</li><li>Se puede utilizar la <strong>barra de búsqueda</strong> para filtrar rápidamente una cubierta en particular.</li><li>Al seleccionar una cubierta, se despliega su trazabilidad en el panel principal (a la derecha).</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Es importante aplicar si se quiere filtrar por cubierta</p></div><h2 id="_2-panel-principal-–-detalle-de-trazabilidad" tabindex="-1">2. Panel principal – Detalle de trazabilidad <a class="header-anchor" href="#_2-panel-principal-–-detalle-de-trazabilidad" aria-label="Permalink to &quot;2. Panel principal – Detalle de trazabilidad&quot;">​</a></h2><p>En la parte superior figura el título: <strong>“Trazabilidad de Cubiertas – Detalles”</strong>.</p><p>Cada cubierta seleccionada muestra:</p><h3 id="encabezado-de-la-cubierta" tabindex="-1">Encabezado de la cubierta <a class="header-anchor" href="#encabezado-de-la-cubierta" aria-label="Permalink to &quot;Encabezado de la cubierta&quot;">​</a></h3><p>Ejemplo: <strong>FATE 784063 SR 200 23/23 – Kilómetros: 12000</strong></p><ul><li><strong>Marca / Modelo</strong>: FATE 784063 SR 200</li><li><strong>Medida</strong>: 295 (ejemplo de medida de la cubierta)</li><li><strong>Kilómetros</strong>: acumulado del momento que se registró en sistema.</li></ul><hr><h3 id="detalles-de-movimientos" tabindex="-1">Detalles de movimientos <a class="header-anchor" href="#detalles-de-movimientos" aria-label="Permalink to &quot;Detalles de movimientos&quot;">​</a></h3><p>Cada fila representa un evento o movimiento en la vida útil de la cubierta:</p><table tabindex="0"><thead><tr><th>Columna</th><th>Descripcion</th></tr></thead><tbody><tr><td><strong>Fecha</strong></td><td>Día en que ocurrió el movimiento (ejemplo: 08/09/25).</td></tr><tr><td><strong>Flujo</strong></td><td>Tipo de movimiento registrado (Recapar, Rotación, etc.).</td></tr><tr><td><strong>Depósito</strong></td><td>Lugar físico o depósito donde se realizó la acción (ejemplo: PYL, JCT54, KGC770).</td></tr><tr><td><strong>Movimiento</strong></td><td>Acción realizada: <br>- <em>A colocar</em> (se coloco) <br>- <em>Sale</em> (se retiro)</td></tr><tr><td><strong>PO</strong></td><td>Posicion de en la que ingreso o salio</td></tr><tr><td><strong>Estado</strong></td><td>Situación actual de la cubierta (Usada, Recapada, etc.).</td></tr><tr><td><strong>Proveedor</strong></td><td>Quién realizó el servicio (ejemplo: PYL, Don andres).</td></tr><tr><td><strong>Notas</strong></td><td>Observaciones adicionales (ejemplo: “Se colocaron cubiertas para…”, “Se sacaron del semi…”).</td></tr><tr><td><strong>KM</strong></td><td>Kilómetros registrados en ese evento puntual.</td></tr></tbody></table><h2 id="_3-boton-ver-mas" tabindex="-1">3. Botón <strong>“Ver más”</strong> <a class="header-anchor" href="#_3-boton-ver-mas" aria-label="Permalink to &quot;3. Botón **“Ver más”**&quot;">​</a></h2><p>En algunos registros aparece la opción <strong>VER MÁS</strong>, que permite desplegar información adicional sobre ese movimiento (ejemplo: detalles de órdenes, vehículos involucrados, etc.) <a href="./../../reportes/mantenimientoCubiertas/mantenimientosCubiertasDetalles.html">Ver Reporte de detalles</a>.</p><h2 id="_4-interpretacion-del-reporte" tabindex="-1">4. Interpretación del reporte <a class="header-anchor" href="#_4-interpretacion-del-reporte" aria-label="Permalink to &quot;4. Interpretación del reporte&quot;">​</a></h2><p>Este informe funciona como una <strong>línea de tiempo</strong> que permite responder:</p><ul><li>¿Cuándo se recapó la cubierta y en qué taller?</li><li>¿En qué vehículos fue colocada y en qué fecha?</li><li>¿Cuántas rotaciones tuvo?</li><li>¿Dónde está actualmente y cuál es su estado?</li><li>¿Qué kilómetros lleva acumulados según el sistema?</li></ul><h2 id="_5-usos-practicos" tabindex="-1">5. Usos prácticos <a class="header-anchor" href="#_5-usos-practicos" aria-label="Permalink to &quot;5. Usos prácticos&quot;">​</a></h2><ul><li><strong>Gestión de mantenimiento</strong>: control del ciclo de vida de las cubiertas, planificación de recapados y reemplazos.</li><li><strong>Auditoría</strong>: justificación de movimientos y comprobación de historial ante proveedores.</li><li><strong>Costos</strong>: identificar cuánto rinde cada cubierta según su marca, medida y cantidad de recapados.</li><li><strong>Logística</strong>: conocer en qué depósito o unidad se encuentra una cubierta en cualquier momento.</li></ul>',25)]))}const b=a(o,[["render",l]]);export{m as __pageData,b as default};
